    if (strlen(word) != strlen(anagram_word)) {
        return 0;
    }
    long words_char_num = 1;
    long anagram_word_num = 1;
    for (const char *p = word; *p; p++) {
        words_char_num *= prime_for(*p);
    }
    for (const char *p = anagram_word; *p; p++) {
        anagram_word_num *= prime_for(*p);
    }
