    for (int index = 0; index < plen; index++) {
        if (P[index] == Q[index]) {
            result[index] = integer_input[P[index]];
            break;
        }
        int minimum_value = integer_input[P[index]];
        for (int i = P[index] + 1; i <= Q[index]; i++) {
            if (integer_input[i] < minimum_value) {
                minimum_value = integer_input[i];
